// Structured output: Gemini must answer with exactly this JSON shape.
const schema = {
  type: 'OBJECT',
  properties: {
    is_payment_receipt: { type: 'BOOLEAN' },
    amount: { type: 'NUMBER', nullable: true },
    currency: { type: 'STRING', nullable: true },
    transfer_number: { type: 'STRING', nullable: true },
    date: { type: 'STRING', nullable: true },
    bank: { type: 'STRING', nullable: true },
    recipient: { type: 'STRING', nullable: true },
  },
  required: ['is_payment_receipt'],
};

const prompt = [
  'You read payment receipts (bank transfers, Nequi, Daviplata, PSE, etc.), mostly from Colombia.',
  'Extract the data shown in the image. Do not guess: use null for anything not visible.',
  'amount: the transferred amount as a plain number (Colombian format uses dots for thousands: "$ 50.000" is 50000).',
  'transfer_number: the reference / approval / transaction number exactly as printed.',
  'date: ISO 8601 if possible. is_payment_receipt: false if the image is not a payment receipt.',
].join('\n');

const buffer = await this.helpers.getBinaryDataBuffer(0, 'receipt');
const mimeType = $input.first().binary.receipt.mimeType;

return [{
  json: {
    body: {
      contents: [{ parts: [{ text: prompt }, { inline_data: { mime_type: mimeType, data: buffer.toString('base64') } }] }],
      generationConfig: { temperature: 0, responseMimeType: 'application/json', responseSchema: schema },
    },
  },
}];

// Every path ends here: Gemini answer, fallback answer, or an upstream error.
const order = $('Receipt input').first().json;
const response = $input.first().json;

const unverified = (reason) => [{ json: { ...order, receipt_check: { status: 'unverified', reasons: [reason], extracted: null, model: null } } }];

const text = response?.candidates?.[0]?.content?.parts?.map((p) => p.text).join('');
if (!text) return unverified('No se pudo leer el comprobante automáticamente');

let extracted;
try {
  extracted = JSON.parse(text);
} catch {
  return unverified('La IA devolvió una respuesta inválida');
}

const money = (amount) => new Intl.NumberFormat("es-CO", { style: "currency", currency: order.currency, minimumFractionDigits: 0 }).format(amount);
const normalize = (value) => String(value ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const reasons = [];

if (!extracted.is_payment_receipt) {
  reasons.push('La imagen no parece un comprobante de pago');
} else {
  if (extracted.amount == null) reasons.push('No se ve el monto');
  else if (Math.abs(extracted.amount - order.total) >= 1) reasons.push(`El monto del comprobante (${money(extracted.amount)}) no coincide con el total del pedido (${money(order.total)})`);

  const declared = normalize(order.transfer_number);
  const printed = normalize(extracted.transfer_number);
  if (declared && printed && !printed.includes(declared) && !declared.includes(printed)) {
    reasons.push(`El número de transferencia del comprobante (${extracted.transfer_number}) no coincide con el que escribió el comprador (${order.transfer_number})`);
  } else if (declared && !printed) {
    reasons.push('No se ve el número de transferencia en el comprobante');
  }
}

return [{
  json: {
    ...order,
    receipt_check: {
      status: reasons.length === 0 ? 'match' : 'review',
      reasons,
      extracted,
      model: response.modelVersion ?? null,
    },
  },
}];
